import{compilePromptPack}from"../../core/prompt-pack";import type{ProviderValidationInput}from"../../core/contracts/provider-capability";import{mockCapabilityManifest}from"../../providers/capabilities";import{approvedPromptBlueprint}from"./prompt-pack"
export function compatibleProviderInput():ProviderValidationInput{const promptPack=compilePromptPack(approvedPromptBlueprint("provider-positive")),providerId="mock-provider";return{promptPack,providerId,providerAdapterVersion:"1.0.0",capabilityManifest:mockCapabilityManifest(providerId),authorizationContext:{providerId,authorized:true,allowedPromptPackIds:[promptPack.promptPackId],fallbackProviderIds:[]},validationPolicy:{policyVersion:"1.0.0",minimumCapabilityConfidence:.8,allowEmulatedRequired:true,allowLowRiskAdaptation:true,requireCalibrated:true,allowFallback:false}}}
export function incompatibleProviderInput():ProviderValidationInput{const i=structuredClone(compatibleProviderInput());i.capabilityManifest.capabilities=i.capabilityManifest.capabilities.filter(x=>!["START_FRAME","SOURCE_IMAGE_PRESERVATION","CHARACTER_CONSISTENCY"].includes(x.capability));i.capabilityManifest.calibrationStatus="EXPIRED";i.authorizationContext.authorized=false;return i}
